/**
 * The slice of Unicode character data that CPython's `int()` and `repr()` rely
 * on.  Everything is derived from the engine's own Unicode tables through
 * property escapes, so no data table has to be shipped.
 */

const DECIMAL_DIGIT = /^\p{Nd}$/u;
// CPython treats a character as unprintable when its category is one of
// Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs -- ASCII space being the single exception.
const UNPRINTABLE = /^[\p{C}\p{Z}]$/u;

/** Characters `str.strip()` removes when `int()` parses a literal. */
const PY_SPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

/** Longest run of consecutive `Nd` code points in Unicode (maths digits: 50). */
const MAX_DIGIT_BLOCK = 128;

export function isPySpace(codePoint) {
  return PY_SPACE.has(codePoint);
}

export function isDecimalDigit(codePoint) {
  if (codePoint < 0 || codePoint > 0x10ffff) return false;
  return DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
}

/**
 * Numeric value of any Unicode decimal digit, or -1.
 *
 * Decimal digits always appear as aligned runs of ten code points, and blocks
 * of such runs are contiguous, so the value is the offset from the start of the
 * surrounding contiguous `Nd` block, modulo ten.
 */
export function decimalValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  if (!isDecimalDigit(codePoint)) return -1;
  let blockStart = codePoint;
  for (let step = 0; step < MAX_DIGIT_BLOCK; step += 1) {
    if (!isDecimalDigit(blockStart - 1)) break;
    blockStart -= 1;
  }
  return (codePoint - blockStart) % 10;
}

export function isPrintable(character) {
  if (character === ' ') return true;
  return !UNPRINTABLE.test(character);
}

